sys_script_fix.script:
(function() {

    var vehicle = new GlideRecord('x_1947064_autoca_0_vehicle');
    vehicle.query();

    var total = 0;
    var updated = 0;
    var alreadySet = 0;
    var unmatched = 0;

    while (vehicle.next()) {

        total++;

        var ownerName = vehicle.getValue('owner_name');

        if (!ownerName) {
            unmatched++;
            continue;
        }

        var user = new GlideRecord('sys_user');
        user.addQuery('name', ownerName);
        user.setLimit(1);
        user.query();

        if (user.next()) {

            var userSysId = user.getUniqueValue();

            if (vehicle.getValue('owner') == userSysId) {
                alreadySet++;
                continue;
            }

            vehicle.setValue('owner', userSysId);
            vehicle.update();

            updated++;

        } else {
            unmatched++;
        }
    }

    gs.info('========== OWNER UPDATE RESULT ==========');
    gs.info('TOTAL VEHICLES = ' + total);
    gs.info('UPDATED = ' + updated);
    gs.info('ALREADY SET = ' + alreadySet);
    gs.info('UNMATCHED = ' + unmatched);

})();
